# data.py - loads GTSRB, makes the track-based validation split and builds the DataLoaders.
# Used by train.py, test.py and make_samples.py.
# Source note: adapted from code generated by Claude (Anthropic), Nov 2026.

import numpy as np
from datasets import load_dataset                      # Hugging Face library that reads the parquet files
from sklearn.model_selection import train_test_split  # used for the stratified train/val split
from torch.utils.data import Dataset, DataLoader
from torchvision import transforms as T

# Names of the 9 parquet files in data/: train, clean test and the 7 corrupted copies of test
SPLITS = ["train", "test", "contrast", "gaussian_noise", "impulse_noise",
          "jpeg_compression", "motion_blur", "pixelate", "spatter"]


def load_gtsrb():
    # Returns a dict-like object, so ds["train"], ds["pixelate"] etc. work.
    # Each row has an "image" (PIL image) and a "label" (int 0-42).
    return load_dataset("parquet", data_files={s: f"data/{s}-00000-of-00001.parquet" for s in SPLITS})


def track_split(labels, val_frac=0.15, seed=42):
    # The training set is 888 tracks x 30 near-identical frames of the same physical sign
    # (found in explore.ipynb). We split whole tracks, so the same sign never appears in both
    # train and validation. A random image split would make validation accuracy too optimistic.
    tracks = np.arange(len(labels) // 30)              # one number per track: 0..887
    # labels[::30] = one label per track -> stratify keeps ~15% of each class's tracks in val.
    # random_state fixes the split, so all experiments use exactly the same validation data.
    tr, va = train_test_split(tracks, test_size=val_frac, stratify=labels[::30], random_state=seed)
    # Turn track numbers back into image indices: track t -> images t*30 ... t*30+29
    to_idx = lambda t: (t[:, None] * 30 + np.arange(30)).ravel()
    return to_idx(tr), to_idx(va)


def get_transform(size, augment, pretrained):
    # Normalisation: ResNet was pretrained on ImageNet, so it needs ImageNet's mean/std.
    # For the CNN from scratch, 0.5/0.5 scales pixels from [0, 1] to roughly [-1, 1].
    mean, std = ([0.485, 0.456, 0.406], [0.229, 0.224, 0.225]) if pretrained else ([0.5] * 3, [0.5] * 3)
    # Augmentation (training only): small rotation, shift/zoom, brightness/contrast changes.
    # NO horizontal flip: flipping turns e.g. "turn left" into "turn right", so the label would be wrong.
    aug = [T.RandomRotation(10),                                        # rotate up to +-10 degrees
           T.RandomAffine(0, translate=(0.1, 0.1), scale=(0.9, 1.1)),   # shift up to 10%, zoom 90-110%
           T.ColorJitter(brightness=0.3, contrast=0.3)] if augment else []  # lighting/weather variation
    # Order: resize to a fixed size -> augment -> tensor [3, H, W] with values 0-1 -> normalise
    return T.Compose([T.Resize((size, size)), *aug, T.ToTensor(), T.Normalize(mean, std)])


class GTSRB(Dataset):
    # Bridge between a Hugging Face split and PyTorch.
    # idx = which rows of the split belong to this subset (lets train and val share ds["train"]).
    def __init__(self, split, idx, tf):
        self.split, self.idx, self.tf = split, idx, tf

    def __len__(self):
        # Number of images, so the DataLoader knows when an epoch is over
        return len(self.idx)

    def __getitem__(self, i):
        # Returns image number i of this subset as (tensor, label)
        row = self.split[int(self.idx[i])]
        return self.tf(row["image"].convert("RGB")), row["label"]  # convert("RGB") ensures 3 channels


def get_loaders(ds, size=48, augment=False, pretrained=False, batch_size=64):
    # Used by train.py. Returns (train_loader, val_loader).
    tr_idx, va_idx = track_split(np.array(ds["train"]["label"]))
    train = GTSRB(ds["train"], tr_idx, get_transform(size, augment, pretrained))
    val = GTSRB(ds["train"], va_idx, get_transform(size, False, pretrained))  # never augment validation
    # shuffle=True is important: the data is sorted by track/class, so without it a batch
    # would contain 64 images of the same sign.
    return DataLoader(train, batch_size, shuffle=True), DataLoader(val, batch_size)


def get_test_loader(ds, split, size=48, pretrained=False, batch_size=64):
    # Used by test.py for "test" or one of the 7 corruptions: all images, no augmentation, no shuffling
    data = GTSRB(ds[split], np.arange(len(ds[split])), get_transform(size, False, pretrained))
    return DataLoader(data, batch_size)
